<template>
  <div class="home-container">
    <h1>服装试穿推荐系统</h1>
    <form @submit.prevent="handleSubmit">
      <!-- 性别选择 -->
      <div class="form-group">
        <label for="gender">性别：</label>
        <select id="gender" v-model="form.gender">
          <option value="woman">女性</option>
          <option value="man">男性</option>
        </select>
      </div>
      <!-- 描述输入 -->
      <div class="form-group">
        <label for="description">描述（如：适合商务场合的夏季套装）：</label>
        <textarea id="description" v-model="form.description" required placeholder="请描述您的需求"></textarea>
      </div>
      <!-- 图片上传 -->
      <div class="form-group">
        <label for="user-image">上传照片：</label>
        <input type="file" id="user-image" @change="handleImageUpload" accept="image/*" required />
        <!-- 图片预览 -->
        <div v-if="previewImage" class="image-preview">
          <img :src="previewImage" alt="上传预览" />
        </div>
      </div>
      <button type="submit" :disabled="isFormInvalid">开始试穿</button>
    </form>
  </div>
</template>

<script>
import { ref, computed } from 'vue'
import { useRouter } from 'vue-router'
export default {
  name: 'Home',
  setup() {
    const router = useRouter()
    const form = ref({
      gender: 'woman',
      description: '',
      userImage: null
    })
    const previewImage = ref(null)

    // 处理图片上传并生成预览
    const handleImageUpload = (event) => {
      const file = event.target.files[0]
      if (file) {
        form.value.userImage = file
        const reader = new FileReader()
        reader.onload = (e) => {
          previewImage.value = e.target.result
        }
        reader.readAsDataURL(file)
      }
    }

    // 表单提交，上传图片及数据到后端
    const handleSubmit = async () => {
      if (!form.value.userImage || !form.value.description) {
        alert('请填写所有字段！')
        return
      }
      try {
        const formData = new FormData()
        formData.append('user_image', form.value.userImage)
        formData.append('gender', form.value.gender)
        formData.append('description', form.value.description)
        const response = await fetch('/api/upload', {
          method: 'POST',
          body: formData
        })
        const result = await response.json()
        if (result.status === 'success') {
          // 将 session_id 存入 localStorage 或状态管理
          localStorage.setItem('current_session_id', result.session_id)
          router.push('/processing')
        } else {
          alert('上传失败：' + result.error)
        }
      } catch (error) {
        console.error('提交失败:', error)
        alert('网络错误，请重试！')
      }
    }

    const isFormInvalid = computed(() => !form.value.userImage || !form.value.description)

    return {
      form,
      previewImage,
      handleImageUpload,
      handleSubmit,
      isFormInvalid
    }
  }
}
</script>

