<template>
  <div class="processing-container">
    <h2>处理进度</h2>
    <div class="progress-bar">
      <div class="progress" :style="{ width: progress + '%' }">{{ progress }}%</div>
    </div>
    <p>{{ statusMessage }}</p>
    <button @click="checkStatus">刷新状态</button>
    <button @click="goBack">返回主页</button>
  </div>
</template>

<script>
import { ref, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
export default {
  name: 'Processing',
  setup() {
    const router = useRouter()
    const session_id = localStorage.getItem('current_session_id')
    const progress = ref(0)
    const statusMessage = ref('任务已提交...')
    let intervalId = null

    // 轮询获取任务状态
    const checkStatus = async () => {
      try {
        const response = await fetch(`/api/process?session_id=${session_id}`)
        const data = await response.json()
        progress.value = data.progress || 0
        statusMessage.value = data.message || ''
      } catch (error) {
        console.error('查询状态失败:', error)
        statusMessage.value = '无法获取进度，请稍后再试。'
      }
    }

    onMounted(() => {
      intervalId = setInterval(checkStatus, 2000)
    })

    onUnmounted(() => {
      clearInterval(intervalId)
    })

    const goBack = () => {
      localStorage.removeItem('current_session_id')
      router.push('/')
    }

    return {
      progress,
      statusMessage,
      checkStatus,
      goBack
    }
  }
}
</script>

