<template>
  <div class="results-container">
    <h2>试穿结果</h2>
    <div v-if="results.length === 0" class="no-results">
      暂无结果，请稍后刷新...
    </div>
    <div v-else class="clothing-gallery">
      <div v-for="item in results" :key="item.task_id" class="clothing-item">
        <img :src="item.image_url" :alt="`试穿结果-${item.task_id}`" />
        <div class="item-details">
          <p>评分：{{ item.score }}</p>
          <p>关键词：{{ item.reason }}</p>
          <a :href="item.purchase_link" target="_blank">
            <button class="purchase-btn">购买链接</button>
          </a>
        </div>
      </div>
    </div>
    <button @click="goBack">返回主页</button>
  </div>
</template>

<script>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
export default {
  name: 'Results',
  setup() {
    const router = useRouter()
    const session_id = localStorage.getItem('current_session_id')
    const results = ref([])

    const fetchResults = async () => {
      try {
        const response = await fetch(`/api/get_results?session_id=${session_id}`)
        const data = await response.json()
        // 拼接后端返回的相对图片路径
        results.value = data.results.map(resultItem => ({
          ...resultItem,
          image_url: `/api/results/${resultItem.image_url}`
        }))
      } catch (error) {
        console.error('获取结果失败:', error)
        alert('无法获取结果，请重试或联系管理员！')
      }
    }

    onMounted(() => {
      fetchResults()
    })

    const goBack = () => {
      localStorage.removeItem('current_session_id')
      router.push('/')
    }

    return {
      results,
      goBack
    }
  }
}
</script>

