<template>
  <div class="logs-container">
    <h2>日志查看</h2>
    <select v-model="selectedLogType" @change="fetchLogs">
      <option value="getImgURL">图片上传日志</option>
      <option value="tryonAndquery">试穿日志</option>
      <option value="refinerAndquery">细化日志</option>
      <option value="save_result">保存结果日志</option>
    </select>
    <div class="log-content">
      <pre v-if="logs">{{ logs }}</pre>
      <p v-else>请选择日志类型。</p>
    </div>
  </div>
</template>

<script>
import { ref } from 'vue'
export default {
  name: 'Logs',
  setup() {
    const selectedLogType = ref('getImgURL')
    const logs = ref('')

    const fetchLogs = async () => {
      try {
        const response = await fetch(`/api/get_logs?type=${selectedLogType.value}`)
        const data = await response.json()
        logs.value = JSON.stringify(data.logs, null, 2)
      } catch (error) {
        console.error('获取日志失败:', error)
        logs.value = '日志获取失败，请重试。'
      }
    }

    return {
      selectedLogType,
      logs,
      fetchLogs
    }
  }
}
</script>

